#ifndef TILE_DATA_H
#define TILE_DATA_H

/**
 * @file tile_data.h
 * @brief The map's metatiles (tile_defs_data.asm) and their palette
 *        (tile_palette_data.asm).
 *
 * Generated by scripts/ase2tiles.py from assets/Tilesheet.aseprite: do not edit.
 *
 * Each metatile is drawn through one palette bank: a map tile's attribute
 * is TILE_BANK(m) << 4. TILE_BANK() takes a metatile number that is a
 * constant (a literal, or a macro naming one).
 */

#include "hw/nge_palette.h"

#define TILE_PALETTE_PAGE   133  /**< SECTION PAGE_133 in tile_palette_data.asm. */
#define TILE_PALETTE_BANKS  1    /**< Banks in tile_palette, 16 entries each. */
#define TILE_PALETTE_ENTRIES 16  /**< Entries in tile_palette: load them from index 0. */
#define TILE_METATILES      15   /**< Metatiles in the tileset, tile 0 included. */

#define TILE_BANK_0  0
#define TILE_BANK_1  0
#define TILE_BANK_2  0
#define TILE_BANK_3  0
#define TILE_BANK_4  0
#define TILE_BANK_5  0
#define TILE_BANK_6  0
#define TILE_BANK_7  0
#define TILE_BANK_8  0
#define TILE_BANK_9  0
#define TILE_BANK_10  0
#define TILE_BANK_11  0
#define TILE_BANK_12  0
#define TILE_BANK_13  0
#define TILE_BANK_14  0

/** A metatile's bank, from a metatile number that is a constant. */
#define TILE_BANK(m)    TILE_BANK_X(m)
#define TILE_BANK_X(m)  TILE_BANK_##m

extern const nge_palette_entry_9_t tile_palette[];

#endif
